-- Historical snapshot preservation only; no current map admission.
CREATE TABLE region_atlas_document_receipt (id INTEGER PRIMARY KEY CHECK(id=1), source_sha256 TEXT NOT NULL, object_sha256 TEXT NOT NULL, actor TEXT NOT NULL, reason TEXT NOT NULL) STRICT;
CREATE TABLE region_atlas_document_document (row_id INTEGER PRIMARY KEY, parent_id INTEGER NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), shape INTEGER NOT NULL CHECK(shape>=0), "schema" TEXT, "as_of" TEXT, "map_note" TEXT, "attribution" TEXT, UNIQUE(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_epoch (row_id INTEGER PRIMARY KEY, parent_id INTEGER NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), shape INTEGER NOT NULL CHECK(shape>=0), "absolute_date" TEXT, "id" TEXT, "label" TEXT, "source" TEXT, UNIQUE(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_selection (row_id INTEGER PRIMARY KEY, parent_id INTEGER NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), shape INTEGER NOT NULL CHECK(shape>=0), "as_of" TEXT, "decision_kind" TEXT, "reason" TEXT, UNIQUE(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_build_inputs (row_id INTEGER PRIMARY KEY, parent_id INTEGER NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), shape INTEGER NOT NULL CHECK(shape>=0), "boundary" TEXT, "selection" TEXT, "selection_sha256" TEXT, "source_root" TEXT, UNIQUE(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_comparison_boundary (row_id INTEGER PRIMARY KEY, parent_id INTEGER NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), shape INTEGER NOT NULL CHECK(shape>=0), "current_boundary" INTEGER, "effective_year" TEXT, "path" TEXT, "policy" TEXT, "sha256" TEXT, "source_id" TEXT, "source_root" TEXT, UNIQUE(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_selection_epoch (row_id INTEGER PRIMARY KEY, parent_id INTEGER NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), shape INTEGER NOT NULL CHECK(shape>=0), "absolute_date" TEXT, "id" TEXT, "label" TEXT, "source" TEXT, UNIQUE(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_osm (row_id INTEGER PRIMARY KEY, parent_id INTEGER NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), shape INTEGER NOT NULL CHECK(shape>=0), "acquired_at" TEXT, "complete_official_roster" INTEGER, "modified_at" TEXT, "path" TEXT, "policy" TEXT, "sha256" TEXT, "snapshot_at" TEXT, "snapshot_basis" TEXT, UNIQUE(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_selected_boundary (row_id INTEGER PRIMARY KEY, parent_id INTEGER NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), shape INTEGER NOT NULL CHECK(shape>=0), "attribution" TEXT, "authority" TEXT, "cleanup_policy" TEXT, "coverage_tolerance_m2" TEXT, "filter" TEXT, "license" TEXT, "measurement_crs" TEXT, "overlap_excess_m2" TEXT, "path" TEXT, "precision_policy" TEXT, "publication_commit_date" TEXT, "retrieved_on" TEXT, "selected_union_area_m2" TEXT, "sha256" TEXT, "source_crs" TEXT, "source_districts" TEXT, "source_effective_date" TEXT, "source_id" TEXT, "source_regions" TEXT, "source_url" TEXT, UNIQUE(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_selection_terrain (row_id INTEGER PRIMARY KEY, parent_id INTEGER NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), shape INTEGER NOT NULL CHECK(shape>=0), "observation_date" TEXT, "observation_date_reason" TEXT, "policy" TEXT, "source_object_modified_month" TEXT, "source_object_modified_precision" TEXT, UNIQUE(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_district (row_id INTEGER PRIMARY KEY, parent_id INTEGER NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), shape INTEGER NOT NULL CHECK(shape>=0), "id" TEXT, "name" TEXT, UNIQUE(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_district_region_ids (parent_id INTEGER NOT NULL REFERENCES region_atlas_document_district(row_id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), value TEXT NOT NULL, PRIMARY KEY(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_coverage (row_id INTEGER PRIMARY KEY, parent_id INTEGER NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), shape INTEGER NOT NULL CHECK(shape>=0), "region_count" TEXT, "district_count" TEXT, "selected_union_area_m2" TEXT, "gap_m2" TEXT, "overlap_m2" TEXT, "regions_without_stations" TEXT, "official_real_world_completeness" TEXT, UNIQUE(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_candidate_status (row_id INTEGER PRIMARY KEY, parent_id INTEGER NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), shape INTEGER NOT NULL CHECK(shape>=0), "assigned" TEXT, "outside" TEXT, "quarantine" TEXT, UNIQUE(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_region (row_id INTEGER PRIMARY KEY, parent_id INTEGER NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), shape INTEGER NOT NULL CHECK(shape>=0), "id" TEXT, "name" TEXT, "district_id" TEXT, "district_name" TEXT, "area_m2" TEXT, UNIQUE(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_region_station_ids (parent_id INTEGER NOT NULL REFERENCES region_atlas_document_region(row_id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), value TEXT NOT NULL, PRIMARY KEY(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_region_facility_ids (parent_id INTEGER NOT NULL REFERENCES region_atlas_document_region(row_id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), value TEXT NOT NULL, PRIMARY KEY(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_profile (row_id INTEGER PRIMARY KEY, parent_id INTEGER NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), shape INTEGER NOT NULL CHECK(shape>=0), "anchor_scope" TEXT, UNIQUE(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_anchor (row_id INTEGER PRIMARY KEY, parent_id INTEGER NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), shape INTEGER NOT NULL CHECK(shape>=0), "id" TEXT, "kind" TEXT, "name" TEXT, "relation" TEXT, "source_object_id" TEXT, "source_ref" TEXT, UNIQUE(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_anchor_tag (parent_id INTEGER NOT NULL REFERENCES region_atlas_document_anchor(row_id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), key TEXT NOT NULL, value TEXT NOT NULL, PRIMARY KEY(parent_id,ordinal), UNIQUE(parent_id,key)) STRICT;
CREATE TABLE region_atlas_document_candidate_counts (row_id INTEGER PRIMARY KEY, parent_id INTEGER NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), shape INTEGER NOT NULL CHECK(shape>=0), "access" TEXT, "all_candidates" TEXT, "building_context" TEXT, "facility" TEXT, "landscape" TEXT, "other_context" TEXT, "road_context" TEXT, "subway_station" TEXT, "rail_station" TEXT, UNIQUE(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_landuse (row_id INTEGER PRIMARY KEY, parent_id INTEGER NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), shape INTEGER NOT NULL CHECK(shape>=0), "object_count" TEXT, "tag" TEXT, UNIQUE(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_terrain (row_id INTEGER PRIMARY KEY, parent_id INTEGER NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), shape INTEGER NOT NULL CHECK(shape>=0), "max_m" TEXT, "mean_m" TEXT, "method" TEXT, "min_m" TEXT, "observation_date" TEXT, "relief_m" TEXT, "sample_count" TEXT, "source_object_modified_month" TEXT, UNIQUE(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_terrain_source_refs (parent_id INTEGER NOT NULL REFERENCES region_atlas_document_terrain(row_id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), value TEXT NOT NULL, PRIMARY KEY(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_content (row_id INTEGER PRIMARY KEY, parent_id INTEGER NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), shape INTEGER NOT NULL CHECK(shape>=0), "source_kind" TEXT, "fictional_epoch" TEXT, "title" TEXT, "summary" TEXT, "livelihood" TEXT, "opening_state" TEXT, "connections" TEXT, "uncertainty" TEXT, "core_station" INTEGER, UNIQUE(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_content_anchor_refs (parent_id INTEGER NOT NULL REFERENCES region_atlas_document_content(row_id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), value TEXT NOT NULL, PRIMARY KEY(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_content_canon_refs (parent_id INTEGER NOT NULL REFERENCES region_atlas_document_content(row_id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), value TEXT NOT NULL, PRIMARY KEY(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_content_polity_contexts (parent_id INTEGER NOT NULL REFERENCES region_atlas_document_content(row_id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), value TEXT NOT NULL, PRIMARY KEY(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_content_inhabitants (parent_id INTEGER NOT NULL REFERENCES region_atlas_document_content(row_id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), value TEXT NOT NULL, PRIMARY KEY(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_content_shortages (parent_id INTEGER NOT NULL REFERENCES region_atlas_document_content(row_id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), value TEXT NOT NULL, PRIMARY KEY(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_production (row_id INTEGER PRIMARY KEY, parent_id INTEGER NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), shape INTEGER NOT NULL CHECK(shape>=0), UNIQUE(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_production_outputs (parent_id INTEGER NOT NULL REFERENCES region_atlas_document_production(row_id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), value TEXT NOT NULL, PRIMARY KEY(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_production_requires (parent_id INTEGER NOT NULL REFERENCES region_atlas_document_production(row_id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), value TEXT NOT NULL, PRIMARY KEY(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_hazard (row_id INTEGER PRIMARY KEY, parent_id INTEGER NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), shape INTEGER NOT NULL CHECK(shape>=0), "kind" TEXT, "description" TEXT, UNIQUE(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_action (row_id INTEGER PRIMARY KEY, parent_id INTEGER NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), shape INTEGER NOT NULL CHECK(shape>=0), "id" TEXT, "label" TEXT, "target_ref" TEXT, "tradeoff" TEXT, UNIQUE(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_cost (row_id INTEGER PRIMARY KEY, parent_id INTEGER NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), shape INTEGER NOT NULL CHECK(shape>=0), "resource" TEXT, "amount" TEXT, "unit" TEXT, UNIQUE(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_outcome (row_id INTEGER PRIMARY KEY, parent_id INTEGER NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), shape INTEGER NOT NULL CHECK(shape>=0), "kind" TEXT, "effect" TEXT, UNIQUE(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_building (row_id INTEGER PRIMARY KEY, parent_id INTEGER NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), shape INTEGER NOT NULL CHECK(shape>=0), "anchor_ref" TEXT, "name" TEXT, "observed_use" TEXT, "river" TEXT, "opening_use" TEXT, "how" TEXT, "role" TEXT, "observed_levels" TEXT, "observed_levels_source" TEXT, UNIQUE(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_floor (row_id INTEGER PRIMARY KEY, parent_id INTEGER NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), shape INTEGER NOT NULL CHECK(shape>=0), level_number TEXT, level_text TEXT, "label" TEXT, "state" TEXT, "contents" TEXT, "condition" TEXT, UNIQUE(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_territory (row_id INTEGER PRIMARY KEY, parent_id INTEGER NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), shape INTEGER NOT NULL CHECK(shape>=0), "status" TEXT, UNIQUE(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_holder (row_id INTEGER PRIMARY KEY, parent_id INTEGER NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), shape INTEGER NOT NULL CHECK(shape>=0), "polity" TEXT, "control" TEXT, UNIQUE(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_neighbor (row_id INTEGER PRIMARY KEY, parent_id INTEGER NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), shape INTEGER NOT NULL CHECK(shape>=0), "region_id" TEXT, "shared_boundary_m" TEXT, "travel_edge" INTEGER, UNIQUE(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_polygon (row_id INTEGER PRIMARY KEY, parent_id INTEGER NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), shape INTEGER NOT NULL CHECK(shape>=0), "type" TEXT, UNIQUE(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_site (row_id INTEGER PRIMARY KEY, parent_id INTEGER NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), shape INTEGER NOT NULL CHECK(shape>=0), "id" TEXT, "name" TEXT, "named" INTEGER, "primary_region_id" TEXT, UNIQUE(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_site_kinds (parent_id INTEGER NOT NULL REFERENCES region_atlas_document_site(row_id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), value TEXT NOT NULL, PRIMARY KEY(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_site_tag (parent_id INTEGER NOT NULL REFERENCES region_atlas_document_site(row_id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), key TEXT NOT NULL, value TEXT NOT NULL, PRIMARY KEY(parent_id,ordinal), UNIQUE(parent_id,key)) STRICT;
CREATE TABLE region_atlas_document_site_region_ids (parent_id INTEGER NOT NULL REFERENCES region_atlas_document_site(row_id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), value TEXT NOT NULL, PRIMARY KEY(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_ring (row_id INTEGER PRIMARY KEY, parent_id INTEGER NOT NULL REFERENCES region_atlas_document_polygon(row_id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), UNIQUE(parent_id,ordinal)) STRICT;
CREATE TABLE region_atlas_document_point (parent_id INTEGER NOT NULL REFERENCES region_atlas_document_ring(row_id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), x_decimal TEXT NOT NULL, y_decimal TEXT NOT NULL, PRIMARY KEY(parent_id,ordinal)) STRICT;
